                Animal ani = (Animal)creature;
                // if the animal is not infected or is immuned
                if(!ani.getIsInfected() || ani.getIsImmuned()){  
                    existDisease = false;
                }
                else{
                    existDisease = true;
                }
            }
        }

        return existDisease;
    }
}

