public class PopEquiv {
    // Salmon, Cod, Seaweed, Shark, Whale  (population-priority order)
    static final double[] P = {0.08, 0.08, 0.03, 0.04, 0.03};
    public static void main(String[] a) {
        int DEPTH = 80, WIDTH = 120;

        // OLD: hand-written else-if cascade (no spawn draws — identical on both sides)
        Random r1 = new Random(1111);
        int[] oldSel = new int[DEPTH*WIDTH]; int k1 = 0;
        for (int row = 0; row < DEPTH; row++)
            for (int col = 0; col < WIDTH; col++) {
                int sel;
                if (r1.nextDouble() <= P[0]) sel = 0;
                else if (r1.nextDouble() <= P[1]) sel = 1;
                else if (r1.nextDouble() <= P[2]) sel = 2;
                else if (r1.nextDouble() <= P[3]) sel = 3;
                else if (r1.nextDouble() <= P[4]) sel = 4;
                else sel = -1;
                oldSel[k1++] = sel;
            }
        // a marker draw to detect stream misalignment after populate
        long oldAfter = r1.nextLong();

        // NEW: for-loop-with-break (the refactored form)
        Random r2 = new Random(1111);
        int[] newSel = new int[DEPTH*WIDTH]; int k2 = 0;
        for (int row = 0; row < DEPTH; row++)
            for (int col = 0; col < WIDTH; col++) {
                int sel = -1;
                for (int i = 0; i < P.length; i++) {
                    if (r2.nextDouble() <= P[i]) { sel = i; break; }
                }
                newSel[k2++] = sel;
            }
        long newAfter = r2.nextLong();

